"""Page Object class for the Single Sign-On (SSO) Login window typically associated with Monaco. The SSO login window can be
launched by either the Monaco.exe or the AdaptivePlanningWorkflow.exe AUT process. This class serves as an interface to the
SSO window and provides a mechanism to wait (and retry) for either process to start and attach to it. It also sets the
correct Squish application context for the low level SSO interaction functions depending on the AUT process used to launch
the SSO login window.
"""

import logging
from .. interactions import SSOLoginFuncs
import interops.libraries.desktop.aut_manager as AutManager
from interops.libraries.monaco import MonacoAutController
from interops.libraries.squish_actions.constants import MONACO_SCRIPTING_APP_NAME, MONACO_APP_NAME

logger = logging.getLogger(__name__)


class SingleSignOnLogin():
    '''
    Page Object Class for the Single Sign-On (SSO) window used for logging in and approving plans in Monaco with the specified
    username and password.

    Args:
        hostAddress (str): The host address of the Monaco system for the Single Sign-On (SSO) window
        autForSSO (str): The name of the AUT process used to launch the SSO login window. Can be either "Monaco" or "AdaptivePlanningWorkflow"
        autAttachRetries (int): The number of times to attempt attaching to the AUT process used to launch the SSO login window. This serves
                                as a waiting mechanism to wait for the .exe process to start
        killExistingListenProess (bool): If True, kills any existing Squish process listening on the port
        launchNewListenProcess (bool): If True, launches a new Squish process to listen on the port (this needs to be set to True if the
                                        SingleSignOnLogin object has already been used to attach to a different process from the current one)
    '''
    def __init__(self, hostAddress: str, autForSSO: str = MONACO_APP_NAME, autAttachRetries: int = 5,
                 killExistingListenProess: bool=False, launchNewListenProcess: bool=False):
        self.sso_login_host_address = hostAddress
        self.sso_login_driver = None

        # Single Sign On interaction relies on Squish's image verification as the SSO IAM login is a web form embedded in an app window, so
        # the objects are not visible to Squish. In order to use the image verification method, Squish first needs to attach to the correct
        # AUT process (either Monaco.exe or AdaptivePlanningWorkflow.exe).
        if autForSSO == "Monaco":
            self.aut_process = MONACO_APP_NAME
        elif autForSSO == "AdaptivePlanningWorkflow":
            self.aut_process = MONACO_SCRIPTING_APP_NAME
        else:
            raise RuntimeError("Unable to attach to AUT process. Invalid AUT process name given")

        if not self.__attach_to_aut_process(autAttachRetries, killExistingListenProess, launchNewListenProcess):
            raise RuntimeError('Failed to attach to an AUT for the SSO login window!')

        # Set the correct AUT context name for the low level SSO interaction functions in sso_login_funcs.py
        SSOLoginFuncs.set_sso_aut_process(self.aut_process)


    def __attach_to_aut_process(self, attachRetries: int = 2, killExistingProcess: bool=False, launchNewStartAutProcess: bool=False) -> bool:
        '''
        Attempts to attach repeatedly to either Monaco.exe or AdaptivePlanningWorkflow.exe process for the
        no. of retries specified. This also serves as a waiting mechanism to wait for the .exe process to start.
        Only the outer SSO login window is recognised by Squish and this can be started by either of the two processes.

        Args:
            attachRetries (int): The number of times to attempt attaching to the process used to start the SSO login window
            killExistingProcess (bool): If True, kills any existing Squish process listening on the port
            launchNewStartAutProcess (bool): If True, launches a new Squish process to listen on the port (this needs to be set to True if the
                                            SingleSignOnLogin object has already been used to attach to a different process from the current one)
        '''
        if str(AutManager.get_current_app_context()) !=  self.aut_process:
            if self.aut_process == MONACO_APP_NAME:
                sso_login_driver = MonacoAutController.monaco_aut(serverAddress=self.sso_login_host_address, serverPort=4322)
            elif self.aut_process == MONACO_SCRIPTING_APP_NAME:
                sso_login_driver = MonacoAutController.monaco_script_aut(serverAddress=self.sso_login_host_address, serverPort=4322)
            for i in range(attachRetries):
                try:
                    print(f"SSO login window attach attempt no. {i+1}")
                    self.sso_login_driver = sso_login_driver.attach_to_aut(
                        kill_existing_process=killExistingProcess, launch_new_startwinaut=launchNewStartAutProcess, get_running_aut_pid_retries=50)
                    return True
                except Exception as e:
                    logger.info(f"Failed to attach to SSO login window on attempt no: {i+1}. Error: {e}.")
        else:
            logger.info("SSO login window AUT already attached")
            return True
        return False


    def login_user(self, username: str, password: str, detachFromAut: bool=True) -> None:
        '''
        Login using Single Sign-On (SSO) with the given username and password.

        Args:
            username (str): The username text string to login with
            password (str): The password text string to login with
        '''
        SSOLoginFuncs.enter_username(username)
        SSOLoginFuncs.enter_password(password)
        SSOLoginFuncs.click_sign_in_button()

        # Detach SSO login window page object Squish handle from the current AUT
        # to allow other page objects to attach to it or other AUTs
        if detachFromAut:
            try:
                self.sso_login_driver.detach()  # type: ignore
            except Exception as e:
                # Log the error but do not raise it to prevent script from terminating, as the sso_login_driver
                # may not have an app handle depending on how the SSO login window was launched
                logger.info(f"Unable to detach from SSO login window AUT. Info: {e}")
